import Foundation
import XCTest
@testable import Butler

@MainActor
final class InventoryOperationCodingTests: XCTestCase {
    func testLegacyPayloadCanDecodeAndEncodeOffMainActorWithoutChangingWireFormat() async throws {
        // A literal old payload, not an expectation generated by the encoder under test.
        let json = Data(#"{"type":"closeLot","payload":{"lotID":"00000000-0000-0000-0000-000000000017","state":"discarded","expectedRevision":9,"evidence":[]}}"#.utf8)
        let encoded = try await Task.detached {
            let operation = try InventoryOperationCoding.makeJSONDecoder().decode(InventoryOperation.self, from: json)
            guard case .closeLot(let close) = operation else { throw CocoaError(.coderInvalidValue) }
            guard close.lotID.uuidString == "00000000-0000-0000-0000-000000000017",
                  close.state == .discarded, close.expectedRevision == 9,
                  close.quantityBeforeClosing == nil else { throw CocoaError(.coderInvalidValue) }
            return try InventoryOperationCoding.makeJSONEncoder().encode(operation)
        }.value
        let expected = try JSONSerialization.jsonObject(with: json) as! NSDictionary
        XCTAssertEqual(try JSONSerialization.jsonObject(with: encoded) as? NSDictionary, expected)
    }

    func testDateAndQuantityPayloadsRetainValuesAcrossActors() async throws {
        let json = Data(#"{"schemaVersion":1,"planID":"00000000-0000-0000-0000-000000000001","inputID":"00000000-0000-0000-0000-000000000002","operations":[{"operationID":"00000000-0000-0000-0000-000000000003","operation":{"type":"setLotDate","payload":{"lotID":"00000000-0000-0000-0000-000000000017","kind":"plannedUseByDate","date":"2026-10-03T01:02:03Z","expectedRevision":4,"evidence":[]}}},{"operationID":"00000000-0000-0000-0000-000000000004","operation":{"type":"adjustQuantity","payload":{"lotID":"00000000-0000-0000-0000-000000000017","delta":-3,"expectedRevision":7,"evidence":[]}}}],"unresolvedFields":[]}"#.utf8)
        let plan = try await Task.detached {
            try InventoryOperationCoding.makeJSONDecoder().decode(InventoryOperationPlan.self, from: json)
        }.value
        guard case .setLotDate(let date) = plan.operations[0].operation,
              case .adjustQuantity(let quantity) = plan.operations[1].operation else {
            return XCTFail("Operation tags changed")
        }
        XCTAssertEqual(date.kind, .plannedUseBy)
        XCTAssertEqual(date.date?.timeIntervalSince1970, 1_790_989_323)
        XCTAssertEqual(date.expectedRevision, 4)
        XCTAssertEqual(quantity.delta, -3)
        XCTAssertEqual(quantity.expectedRevision, 7)
        let encoded = try await Task.detached {
            try InventoryOperationCoding.makeJSONEncoder().encode(plan)
        }.value
        XCTAssertEqual(try JSONSerialization.jsonObject(with: encoded) as? NSDictionary,
                       try JSONSerialization.jsonObject(with: json) as? NSDictionary)
    }
}
